    shortLivedToken = token,
    locale = LOCALE.ENGLISH,
    almatarFlowFinishedCallback = { /* flow closed */ },
    sdkLaunchCallback = object : SdkLaunchCallback {
        override fun onError(error: Throwable) { /* handle */ }
    },
)

modes.code:
AlmatarAppInitializer.launchHotels(
    locale = LOCALE.ENGLISH,
    almatarFlowFinishedCallback = { /* the user left the SDK */ },
    generateTokenImpl = { callback -> callback(token, refreshToken, null) },
    startPaymentFlowImpl = { bookingId, amount, bookingKey, productType, paymentFlowCallback ->
        paymentFlowCallback(PaymentState.LOADING)
        // Charge the user in your own checkout.
        myCheckout.pay(bookingId, amount) { result ->
            when (result) {
                is PayResult.Paid -> paymentFlowCallback(PaymentState.SUCCESS)
                is PayResult.Cancelled -> paymentFlowCallback(PaymentState.CANCELLED)
                is PayResult.Failed -> paymentFlowCallback(PaymentState.FAILURE(result.message))
            }
        }
    },
)

